def scaleToRange(values, newMin=0, newMax=1):	"""Scales data between ranges. With just one arg the range is between 0 and 1."""			newValues	= []	oldMin	= min(values)	oldMax	= max(values)	oldRange	= (oldMax*1.0) - oldMin	newRange	= newMax - newMin	ratio	= newRange/oldRange		for x in values:		scaling = ((x-oldMin) * ratio + newMin)		newValues.append(scaling)	return newValues

def scaleValToRng(value, oldMin=.001875, oldMax=.31375, newMin=1, newMax=39):	"""Scales a value within a range to it's equivalent in a new range."""	oldRange	= (oldMax*1.0) - oldMin	newRange	= newMax - newMin	ratio	= newRange/oldRange		scaledValue = ((value - oldMin) * ratio + newMin)	return scaledValue
